test("見出しの部分の後に箇条書きを続けると、見出しは箇条書きにならず、項目ごとの段落になる", () => {
  const s = slide("k");
  text(s, [{ text: "見出し", bold: true }, ...bullets(["a", "b"])], 0, 0, 1, 1);
  text(s, [{ text: "a", bullet: true }, { text: "b", bullet: true }], 0, 0, 1, 1);
